  static List<String> messagesForLocale(Locale locale) {
    switch (locale.languageCode) {
      case 'en':
        return _englishMessages;
      case 'es':
        return _spanishMessages;
      case 'nl':
        return _dutchMessages;
      case 'tr':
      default:
        return messages;
    }
  }

  static String getRandomMessage([Locale? locale]) {
    final selectedMessages = locale == null
        ? messages
        : messagesForLocale(locale);
    if (selectedMessages.isEmpty) {
      return 'Küçük adımlar büyük fark yaratır.';
    }

    final random = Random();
    return selectedMessages[random.nextInt(selectedMessages.length)];
  }

  static Future<bool> isEnabled() async {
    final prefs = await SharedPreferences.getInstance();
    return prefs.getBool(_enabledKey) ?? true;
  }

  static Future<void> setEnabled(bool enabled) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setBool(_enabledKey, enabled);
  }

  static Future<void> showIfEnabled(BuildContext context) async {
    if (!context.mounted) return;

    final enabled = await isEnabled();
    if (!enabled || !context.mounted) return;

    final locale = Localizations.localeOf(context);
    final l = AppLocalizations.of(context);
    final message = getRandomMessage(locale);

    await showDialog<void>(
      context: context,
      barrierDismissible: false,
      barrierColor: Colors.black.withValues(alpha: 0.12),
      builder: (dialogContext) {
        return Dialog(
          insetPadding: const EdgeInsets.symmetric(horizontal: 24),
          backgroundColor: Colors.transparent,
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 420),
            child: Container(
              padding: const EdgeInsets.fromLTRB(20, 16, 20, 20),
              decoration: BoxDecoration(
                gradient: const LinearGradient(
                  colors: [Color(0xFFEFFCF8), Color(0xFFF7F1FF)],
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                ),
                borderRadius: BorderRadius.circular(28),
                border: Border.all(color: const Color(0xFFCFEAE4), width: 1.2),
                boxShadow: [
                  BoxShadow(
                    color: const Color(0xFF9ACFC5).withValues(alpha: 0.28),
                    blurRadius: 18,
                    offset: const Offset(0, 10),
                  ),
                ],
              ),
              child: Stack(
                children: [
                  Padding(
                    padding: const EdgeInsets.only(top: 12, right: 32),
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Container(
                          width: 64,
                          height: 64,
                          decoration: BoxDecoration(
                            color: const Color(0xFFD9F3ED),
                            shape: BoxShape.circle,
                            boxShadow: [
                              BoxShadow(
                                color: const Color(
                                  0xFF9ACFC5,
                                ).withValues(alpha: 0.18),
                                blurRadius: 12,
                                offset: const Offset(0, 6),
                              ),
                            ],
                          ),
                          child: const Icon(
                            Icons.auto_awesome_rounded,
                            color: Color(0xFF2A7D72),
                            size: 30,
                          ),
                        ),
                        const SizedBox(height: 18),
                        Text(
                          l.motivation,
                          textAlign: TextAlign.center,
                          style: const TextStyle(
                            fontSize: 18,
                            fontWeight: FontWeight.w700,
                            color: Color(0xFF275C56),
                          ),
                        ),
                        const SizedBox(height: 12),
                        Text(
                          message,
                          textAlign: TextAlign.center,
                          style: const TextStyle(
                            fontSize: 16,
                            height: 1.7,
                            color: Color(0xFF2E4A46),
                            fontWeight: FontWeight.w500,
                          ),
                        ),
                      ],
                    ),
                  ),
                  Positioned(
                    top: 0,
                    right: 0,
                    child: Material(
                      color: Colors.white.withValues(alpha: 0.8),
                      shape: const CircleBorder(),
                      child: InkWell(
                        customBorder: const CircleBorder(),
                        onTap: () => Navigator.of(dialogContext).pop(),
                        child: const Padding(
                          padding: EdgeInsets.all(8),
                          child: Icon(
                            Icons.close_rounded,
                            size: 20,
                            color: Color(0xFF3B5F5A),
                          ),
                        ),
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
        );
      },
    );
  }
}
